//! 🧬️ Layout artifact — document mutation dispatch. Semantic vocabulary derived from
//! `📸️snapshot/🦀️.rs`'s `LayoutSnapshot` shape (document-root scalars `name`/`print_target`/
//! `data_fields_json`; id-keyed `pages`/`stories`/`links` collections; per-page nested `frames`) —
//! see `.🧬semio/🦑️repo/🎫️tickets/🎆️26/🌙️08/☀️12/SEMANTIC-MUTATIONS-OVERHAUL/`
//! `📓️taxonomy.md`/`📓️derivation-rules.md`. `impl protocol::Mutation`/`SemanticMutation` below are
//! generated by `#[derive(dsl_derive::Mutations)]` — never hand-written.
//!
//! Every triad leaf is mounted from `🦀️.rs`'s `pub mod mutations { ... }` block, one real
//! `pub mod <snake_slug> { pub mod mutation; pub mod diff; pub mod inverse; }` per triad dir below
//! (Wave-C directory + glue trueing, 26/08/12/SEMANTIC-MUTATIONS-OVERHAUL) — the pre-migration
//! generic-name legacy dirs (`add-frame`/`remove-frame`/`pages`/`stories`/`links`/`set-data-fields`/
//! `patch-frame`) and their glue mounts were deleted. This file `use super::*`-reaches those
//! glue-mounted siblings.

use crate::{LayoutDiff, LayoutSnapshot};
use semio_framework_value_derive::{FromValue, ToValue};

use super::{
    change_data_fields, change_frame_columns, change_frame_fill, change_frame_stroke, change_frame_wrap_mode, change_link_path, change_page_height, change_page_width, change_print_target, create_frame, create_link, create_page, create_story,
    delete_frame, delete_link, delete_page, delete_story, edit_story, move_frame, rename_layout, rename_page, reorder_pages, resize_frame, update_page_columns, update_page_margins,
};

//#region 🔖️Mutations
/// 🧬️ Every variant wraps exactly one `protocol::MutationKind<LayoutSnapshot, LayoutMutation>`
/// payload struct declared in the corresponding triad leaf's `🦠️mutation/🦀️.rs`.
#[derive(Clone, Debug, PartialEq, dsl::Mutations, ToValue, FromValue)]
#[cfg_attr(test, derive(serde::Serialize, serde::Deserialize))]
#[mutations(snapshot = LayoutSnapshot, diff = LayoutDiff, schema = "s.layout.layout")]
pub enum LayoutMutation {
    RenameLayout(rename_layout::RenameLayout),
    ChangePrintTarget(change_print_target::ChangePrintTarget),
    ChangeDataFields(change_data_fields::ChangeDataFields),
    CreatePage(create_page::CreatePage),
    DeletePage(delete_page::DeletePage),
    RenamePage(rename_page::RenamePage),
    ChangePageWidth(change_page_width::ChangePageWidth),
    ChangePageHeight(change_page_height::ChangePageHeight),
    UpdatePageMargins(update_page_margins::UpdatePageMargins),
    UpdatePageColumns(update_page_columns::UpdatePageColumns),
    ReorderPages(reorder_pages::ReorderPages),
    CreateStory(create_story::CreateStory),
    DeleteStory(delete_story::DeleteStory),
    EditStory(edit_story::EditStory),
    CreateLink(create_link::CreateLink),
    DeleteLink(delete_link::DeleteLink),
    ChangeLinkPath(change_link_path::ChangeLinkPath),
    CreateFrame(create_frame::CreateFrame),
    DeleteFrame(delete_frame::DeleteFrame),
    MoveFrame(move_frame::MoveFrame),
    ResizeFrame(resize_frame::ResizeFrame),
    ChangeFrameFill(change_frame_fill::ChangeFrameFill),
    ChangeFrameStroke(change_frame_stroke::ChangeFrameStroke),
    ChangeFrameWrapMode(change_frame_wrap_mode::ChangeFrameWrapMode),
    ChangeFrameColumns(change_frame_columns::ChangeFrameColumns),
}

//#endregion 🔖️Mutations

